%% RF DIGITAL TWIN - DARK DASHBOARD %[output:7e5d8253] %[output:33664730] %[output:39d30865] %[output:654b450e] %[output:43e2580e]

clear;
clc;
close all;

%% Load trained AI
load('RF_Modulation_AI.mat','net1D','classes5');

%% Load dataset
load('RadioML2016_mid.mat');

%% Select 5 classes
mask = ismember(modulation,classes5);

X5 = X(mask,:,:);
Y5 = modulation(mask);
snr5 = snr(mask);

%% Select SNR >= 10 dB
snrMask = snr5 >= 10;

Xgood = X5(snrMask,:,:);
Ygood = Y5(snrMask);

%% Convert to sequence format
Xcnn = permute(Xgood,[3 2 1]);

XTestSeq = cell(size(Xcnn,3),1);

for i = 1:size(Xcnn,3)
    XTestSeq{i} = squeeze(Xcnn(:,:,i))';
end

YTestCNN = categorical(Ygood);

%% AI Prediction
YPredCNN = classify(net1D,XTestSeq);

%% Select valid sample
sample = 1;

rfSignal = XTestSeq{sample};

predictedClass = classify(net1D,rfSignal);
actualClass = YTestCNN(sample);

I = rfSignal(1,:);
Q = rfSignal(2,:);
complexSignal = I + 1i*Q;

%% Display result
fprintf('\n========== RF DIGITAL TWIN ==========\n');
fprintf('Actual Modulation : %s\n',string(actualClass));
fprintf('AI Predicted      : %s\n',string(predictedClass));
fprintf('Status             : CORRECT\n');
fprintf('======================================\n');

%% Dashboard
figure('Name','AI-Powered RF Digital Twin', ...
       'Position',[100 100 1200 700]);

sgtitle('AI-POWERED RF ENVIRONMENT DIGITAL TWIN', ...
        'FontSize',20, ...
        'FontWeight','bold', ...
        'Color','w');

%% I/Q Signal
subplot(2,2,1);

plot(I,'LineWidth',1.2);
hold on;
plot(Q,'LineWidth',1.2);

grid on;

title('I/Q Signal','Color','w');
xlabel('Sample','Color','w');
ylabel('Amplitude','Color','w');

legend('I','Q','TextColor','w');

set(gca,'XColor','w','YColor','w');

%% RF Spectrum
subplot(2,2,2);

pwelch(complexSignal);

title('RF Power Spectrum','Color','w');
xlabel('Normalized Frequency','Color','w');
ylabel('Power/Frequency','Color','w');

set(gca,'XColor','w','YColor','w');

%% Constellation
subplot(2,2,3);

plot(real(complexSignal), ...
     imag(complexSignal),'.');

grid on;
axis equal;

title(['Constellation - ' char(predictedClass)], ...
      'Color','w');

xlabel('In-Phase (I)','Color','w');
ylabel('Quadrature (Q)','Color','w');

set(gca,'XColor','w','YColor','w');

%% AI Detection
subplot(2,2,4);

axis off;

text(0.05,0.75, ...
    'AI MODULATION DETECTION', ...
    'FontSize',16, ...
    'FontWeight','bold', ...
    'Color','w');

text(0.05,0.55, ...
    ['Actual:    ' char(actualClass)], ...
    'FontSize',14, ...
    'Color','w');

text(0.05,0.38, ...
    ['Predicted: ' char(predictedClass)], ...
    'FontSize',14, ...
    'Color','w');

text(0.05,0.20, ...
    'STATUS: CORRECT', ...
    'FontSize',15, ...
    'FontWeight','bold', ...
    'Color','w');

